        HelpBlock.p('Адрес Epicbox — это длинный код, который заканчивается на **@** и имя сервера Epicbox, например **…@${hostSettings.epicboxUse}**. Им можно делиться: он нужен, чтобы заплатить, и с ним ничего нельзя забрать.'),
        const HelpBlock.ol(['Откройте [[Получить|Receive]].', 'Скопируйте адрес (или покажите его QR-код) и отправьте тому, кто платит.', 'Платёж сам появится в разделе «Активность».']),
